    Bug 1917465 - Delay initial folder selection until resize observers have fired. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D233988

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index 9ee789fab51..286fdeca4da 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -186,6 +186,11 @@ window.addEventListener("DOMContentLoaded", async event => {
   // (triggered by `folderPane.init` and possibly `restoreState`) are ignored
   // to avoid unnecessarily loading the thread tree or Account Central.
   folderTree.addEventListener("select", folderPane);
+
+  // Delay inital folder selection until after the message list's resize
+  // observer has had a chance to respond to layout changes. Otherwise we
+  // might end up scrolling to the wrong part of the list.
+  await new Promise(resolve => setTimeout(resolve));
   folderTree.dispatchEvent(new CustomEvent("select"));

   mailContextMenu.init();
diff --git a/mail/base/test/browser/browser_markAsRead.js b/mail/base/test/browser/browser_markAsRead.js
index f819dbf5478..d9d8275399e 100644
--- a/mail/base/test/browser/browser_markAsRead.js
+++ b/mail/base/test/browser/browser_markAsRead.js
@@ -193,6 +193,10 @@ async function subtest(testFolder) {

   message = testMessages.getNext();
   Assert.ok(!message.isRead, "message 4 should not be read before load");
+  await TestUtils.waitForCondition(
+    () => secondAbout3Pane.gDBView,
+    "waiting for second tab to select a folder"
+  );
   secondAbout3Pane.threadTree.selectedIndex =
     secondAbout3Pane.gDBView.findIndexOfMsgHdr(message, false);
   await BrowserTestUtils.waitForEvent(window, "MsgLoaded");
diff --git a/mail/components/extensions/parent/ext-mailTabs.js b/mail/components/extensions/parent/ext-mailTabs.js
index 1d99c5caf06..a4fc3e135c0 100644
--- a/mail/components/extensions/parent/ext-mailTabs.js
+++ b/mail/components/extensions/parent/ext-mailTabs.js
@@ -559,6 +559,9 @@ this.mailTabs = class extends ExtensionAPIPersistent {
           const window = await getNormalWindowReady();
           const nativeTab = window.gTabmail.openTab("mail3PaneTab", tabParams);
           await waitForMailTabReady(nativeTab);
+          // Be sure that about:3pane's DOMContentLoaded handler has finished,
+          // or we might not have a selected folder yet.
+          await new Promise(resolve => setTimeout(resolve));
           return updateMailTab(nativeTab, properties);
         },
